post_build.macos:
case "$FORMCOMPILER_PLATFORM" in
  macos-x64) arch=x86_64 ;;
  *) arch=arm64 ;;
esac
python3 setup/package_release.py --platform macos --arch "$arch"

post_build.linux:
case "$FORMCOMPILER_PLATFORM" in
  linux-arm64) arch=arm64 ;;
  *) arch=x86_64 ;;
esac
python3 setup/package_release.py --platform linux --arch "$arch"

post_build.windows:
case "$FORMCOMPILER_PLATFORM" in
  windows-arm64) arch=arm64 ;;
  *) arch=x86_64 ;;
esac
python setup/package_release.py --platform windows --arch "$arch"
